12	// --- Gemini CLI format support ---
13	//
14	// Gemini transcripts are a single JSON object (not JSONL):
15	//
16	//	{"sessionId":"...","messages":[{"id":"...","timestamp":"...","type":"user"|"gemini"|"info","content":"...","toolCalls":[...],"thoughts":[...]}]}
17	//
18	// Key differences from other formats:
19	//   - Assistant messages use type "gemini" (not "assistant")
20	//   - System messages use type "info" and should be dropped
21	//   - Tool calls are at the message level in a "toolCalls" array
22	//   - A message can have both content text and toolCalls
23	//   - Timestamps are ISO strings (not millisecond integers)
24	//   - Token usage is in "tokens" with "input" and "output" fields
25	
26	// geminiDroppedTypes are Gemini message types that carry no transcript-relevant data.
27	var geminiDroppedTypes = map[string]bool{
28		"info": true,
29	}
30	
31	// isGeminiFormat checks whether content is a single JSON object with the
32	// Gemini session shape: top-level "sessionId" and "messages" keys, but NO "info"
33	// key (which distinguishes it from OpenCode format).
34	func isGeminiFormat(content []byte) bool {
35		trimmed := bytes.TrimSpace(content)
36		if len(trimmed) == 0 || trimmed[0] != '{' {
37			return false
38		}
39		var probe struct {
40			SessionID *json.RawMessage `json:"sessionId"`
41			Messages  *json.RawMessage `json:"messages"`
42			Info      *json.RawMessage `json:"info"`
43		}
44		if json.Unmarshal(trimmed, &probe) != nil {
45			return false
46		}
47		return probe.SessionID != nil && probe.Messages != nil && probe.Info == nil
48	}
