50	// geminiMessage mirrors the Gemini message structure for unmarshaling.
51	type geminiMessage struct {
52		ID        string           `json:"id"`
53		Timestamp string           `json:"timestamp"`
54		Type      string           `json:"type"`
55		Content   string           `json:"content"`
56		ToolCalls []geminiToolCall `json:"toolCalls"`
57		Tokens    *geminiTokens    `json:"tokens"`
58	}
59	
60	// geminiTokens holds token usage from a Gemini message.
61	type geminiTokens struct {
62		Input  int `json:"input"`
63		Output int `json:"output"`
64	}
65	
66	// geminiToolCall represents a single tool invocation within a Gemini message.
67	type geminiToolCall struct {
68		ID     string             `json:"id"`
69		Name   string             `json:"name"`
70		Args   json.RawMessage    `json:"args"`
71		Result []geminiToolResult `json:"result"`
72		Status string             `json:"status"`
73	}
74	
75	// geminiToolResult represents a tool result entry from the Gemini format.
76	type geminiToolResult struct {
77		FunctionResponse struct {
78			ID       string `json:"id"`
79			Name     string `json:"name"`
80			Response struct {
81				Output string `json:"output"`
82			} `json:"response"`
83		} `json:"functionResponse"`
84	}
