86	// compactGemini converts a full Gemini session JSON into transcript lines.
87	// opts.StartLine is treated as a message-index offset (not a newline offset)
88	// because the Gemini transcript is a single JSON object.
89	func compactGemini(content []byte, opts MetadataFields) ([]byte, error) {
90		var session struct {
91			Messages []geminiMessage `json:"messages"`
92		}
93		if err := json.Unmarshal(bytes.TrimSpace(content), &session); err != nil {
94			return nil, fmt.Errorf("parsing gemini session: %w", err)
95		}
96	
97		messages := session.Messages
98		if opts.StartLine > 0 {
99			if opts.StartLine >= len(messages) {
100				return []byte{}, nil
101			}
102			messages = messages[opts.StartLine:]
103		}
104	
105		base := newTranscriptLine(opts)
106		var result []byte
107	
108		for _, msg := range messages {
109			if geminiDroppedTypes[msg.Type] {
110				continue
111			}
112	
113			ts, err := json.Marshal(msg.Timestamp)
114			if err != nil {
115				continue
116			}
117	
118			switch msg.Type {
119			case transcript.TypeUser:
120				emitGeminiUser(&result, base, msg, ts)
121			case "gemini":
122				emitGeminiAssistant(&result, base, msg, ts)
123			}
124		}
125	
126		return result, nil
127	}
