129	// emitGeminiUser produces a single user line. Gemini user messages have
130	// plain string content.
131	func emitGeminiUser(result *[]byte, base transcriptLine, msg geminiMessage, ts json.RawMessage) {
132		text := textutil.StripIDEContextTags(msg.Content)
133		if text == "" {
134			return
135		}
136	
137		b, err := json.Marshal([]userTextBlock{{Text: text}})
138		if err != nil {
139			return
140		}
141	
142		line := base
143		line.Type = transcript.TypeUser
144		line.TS = ts
145		line.Content = b
146		appendLine(result, line)
147	}
