149	// emitGeminiAssistant produces a single assistant line. The content array
150	// contains text blocks (from content field) and tool_use blocks (from toolCalls).
151	func emitGeminiAssistant(result *[]byte, base transcriptLine, msg geminiMessage, ts json.RawMessage) {
152		content := make([]map[string]json.RawMessage, 0, 1+len(msg.ToolCalls))
153	
154		if msg.Content != "" {
155			b, err := json.Marshal(transcript.ContentTypeText)
156			if err == nil {
157				text, err := json.Marshal(msg.Content)
158				if err == nil {
159					content = append(content, map[string]json.RawMessage{
160						"type": b,
161						"text": text,
162					})
163				}
164			}
165		}
166	
167		for _, tc := range msg.ToolCalls {
168			b, err := json.Marshal(transcript.ContentTypeToolUse)
169			if err != nil {
170				continue
171			}
172			id, err := json.Marshal(tc.ID)
173			if err != nil {
174				continue
175			}
176			name, err := json.Marshal(tc.Name)
177			if err != nil {
178				continue
179			}
180	
181			toolBlock := map[string]json.RawMessage{
182				"type":   b,
183				"id":     id,
184				"name":   name,
185				"input":  tc.Args,
186				"result": geminiToolResultCompact(tc),
187			}
188			content = append(content, toolBlock)
189		}
190	
191		if len(content) == 0 {
192			return
193		}
194	
195		contentJSON, err := json.Marshal(content)
196		if err != nil {
197			return
198		}
199	
200		line := base
201		line.Type = transcript.TypeAssistant
202		line.TS = ts
203		line.ID = msg.ID
204		line.Content = contentJSON
205		if msg.Tokens != nil {
206			line.InputTokens = msg.Tokens.Input
207			line.OutputTokens = msg.Tokens.Output
208		}
209		appendLine(result, line)
210	}
211	
212	// geminiToolResultCompact builds the compact {"output":"...","status":"..."}
213	// object from a Gemini tool call.
214	func geminiToolResultCompact(tc geminiToolCall) json.RawMessage {
215		output := ""
216		if len(tc.Result) > 0 {
217			output = tc.Result[0].FunctionResponse.Response.Output
218		}
219	
220		r := toolResultJSON{
221			Output: output,
222			Status: "success",
223		}
224		if tc.Status != "" && tc.Status != "success" {
225			r.Status = toolResultStatusError
226		}
227		b, err := json.Marshal(r)
228		if err != nil {
229			return nil
230		}
231		return b
232	}
