545	// extractUserContent separates user message content into text, images, and tool_result entries.
546	// IDE context tags (e.g. <user_query>, <ide_opened_file>) are stripped from user text.
547	func extractUserContent(contentRaw json.RawMessage) userContent {
548		var str string
549		if json.Unmarshal(contentRaw, &str) == nil {
550			return userContent{text: textutil.StripIDEContextTags(str)}
551		}
552	
553		var blocks []json.RawMessage
554		if json.Unmarshal(contentRaw, &blocks) != nil {
555			return userContent{}
556		}
557	
558		var uc userContent
559	
560		for _, blockRaw := range blocks {
561			var block map[string]json.RawMessage
562			if json.Unmarshal(blockRaw, &block) != nil {
563				continue
564			}
565			blockType := unquote(block["type"])
566	
567			switch blockType {
568			case "tool_result":
569				var isErr bool
570				if raw, ok := block["is_error"]; ok {
571					_ = json.Unmarshal(raw, &isErr) //nolint:errcheck // best-effort
572				}
573				uc.toolResults = append(uc.toolResults, toolResultEntry{
574					toolUseID: unquote(block["tool_use_id"]),
575					output:    unquote(block["content"]),
576					isError:   isErr,
577				})
578	
579			case "image":
580				uc.images = append(uc.images, blockRaw)
581	
582			case transcript.ContentTypeText:
583				stripped := textutil.StripIDEContextTags(unquote(block[transcript.ContentTypeText]))
584				if stripped != "" {
585					uc.text += stripped + "\n\n"
586				}
587			}
588		}
589	
590		uc.text = strings.TrimSpace(uc.text)
591		return uc
592	}
